import React from 'react';
import './Table.scss';
import InfoIcon from '@mui/icons-material/Info';

import {
  largeCircleValue1,
  largeCircleValue4,
  largeCircleValue5,
  largeCircleValue8,
  largeCircleValueCenter,
  getSum,
} from '../../functions/calculator';
import { useAppSelector } from '../../hooks/redux';
import { Tooltip } from '@mui/material';
import { calculateResourceMatrix } from '../../functions/calculateResourceMatrix';

export const TableResource = () => {
  const { mainString, userDataPersonal } = useAppSelector((state) => state.storeReducer);
  // const mainString = ['2', '4', '0', '1', '1', '9', '9', '7'];

  const resourceDate = calculateResourceMatrix(userDataPersonal.birth);
  const [dayStr, monthStr, yearStr] = resourceDate.split('.');

  const resourceLarge4 = parseInt(dayStr, 10);
  const resourceLarge1 = parseInt(monthStr, 10);
  const resourceLarge5 = parseInt(yearStr, 10);

  const resourceLarge2 = getSum(resourceLarge1 + resourceLarge4);
  const resourceLarge3 = getSum(resourceLarge1 + resourceLarge5);
  const resourceLarge8 = getSum(resourceLarge4 + resourceLarge1 + resourceLarge5);
  const resourceLarge6 = getSum(resourceLarge4 + resourceLarge8);
  const resourceLargeCenter = getSum(
    resourceLarge1 + resourceLarge4 + resourceLarge5 + resourceLarge8
  );
  const resourceLarge7 = getSum(resourceLarge5 + resourceLarge8);

  return (
    <div className="table_container">
      <h3>КАРТА ЗДОРОВ&apos;Я</h3>
      <table>
        <tbody>
          <tr className="th_header">
            <th className="th_table th_xs td_number"></th>
            <th className="th_table th_large ch-name">Назва чакри</th>
            <th className="th_table th_small">Енергія</th>
            <th className="th_table th_small">Фізика</th>
            <th className="th_table th_small">Емоції</th>
          </tr>
          <tr className="tr_seven">
            <td className="td_number">
              <span>1</span>
            </td>
            <td className="ch-name">
              <div className="tooltip">
                <Tooltip title="волосся, мозок, верхня частина черепа, шкіра голови">
                  <InfoIcon style={{ fontSize: 20, fill: '#9a9ca7' }} />
                </Tooltip>
              </div>
              <div className="info-wrapper">
                <span>Сахасрара</span>
                {/*<span className="ch-info">Місія</span>*/}
              </div>
            </td>
            <td>
              <span> {resourceLarge1}</span>
            </td>
            <td>
              <span>{resourceLarge4} </span>
            </td>
            <td>
              <span>{getSum(resourceLarge4 + resourceLarge1)}</span>
            </td>
          </tr>

          <tr className="tr_six">
            <td className="td_number">
              <span>2</span>
            </td>
            <td className="ch-name">
              <div className="tooltip">
                <Tooltip title="очі, вуха, обличчя, потилиця, верхня щелепа (зуби), тиск">
                  <InfoIcon style={{ fontSize: 20, fill: '#9a9ca7' }} />
                </Tooltip>
              </div>
              <div className="info-wrapper">
                <span>Аджна</span>
                {/*<span className="ch-info">Доля, егрегори</span>*/}
              </div>
            </td>
            <td>
              <span>{getSum(resourceLarge1 + resourceLargeCenter + resourceLarge1)}</span>
            </td>

            <td>
              <span>{getSum(resourceLarge4 + resourceLarge4 + resourceLargeCenter)}</span>
            </td>
            <td>
              <span>
                {getSum(
                  getSum(resourceLarge4 + resourceLarge4 + resourceLargeCenter) +
                    getSum(resourceLarge1 + resourceLargeCenter + resourceLarge1)
                )}
              </span>
            </td>
          </tr>

          <tr className="tr_five">
            <td className="td_number">
              <span>3</span>
            </td>
            <td className="ch-name">
              <div className="tooltip">
                <Tooltip title="горло, нижня щелепа (зуби), щитовидка, плечі, руки, шийний, відділ хребта">
                  <InfoIcon style={{ fontSize: 20, fill: '#9a9ca7' }} />
                </Tooltip>
              </div>
              <div className="info-wrapper">
                <span>Вішудха</span>
                {/*<span className="ch-info">Самосприйняття</span>*/}
              </div>
            </td>

            <td>
              <span>{getSum(resourceLarge1 + resourceLargeCenter)}</span>
            </td>
            <td>
              <span>{getSum(resourceLarge4 + resourceLargeCenter)}</span>
            </td>
            <td>
              <span>
                {getSum(
                  getSum(resourceLarge4 + resourceLargeCenter) +
                    getSum(resourceLarge1 + resourceLargeCenter)
                )}
              </span>
            </td>
          </tr>

          <tr className="tr_eight">
            <td className="td_number">
              <span>4</span>
            </td>
            <td className="ch-name">
              <div className="tooltip">
                <Tooltip title="серце, легені, бронхи, ребра, груди">
                  <InfoIcon style={{ fontSize: 20, fill: '#9a9ca7' }} />
                </Tooltip>
              </div>
              <div className="info-wrapper">
                <span>Анахата</span>
                {/*<span className="ch-info">Відносини, картина світу</span>*/}
              </div>
            </td>
            <td>
              <span>{getSum(resourceLarge1 + resourceLargeCenter + resourceLargeCenter)}</span>
            </td>
            <td>
              <span>{getSum(resourceLargeCenter + resourceLarge4 + resourceLargeCenter)}</span>
            </td>
            <td>
              <span>
                {getSum(
                  getSum(resourceLargeCenter + resourceLarge4 + resourceLargeCenter) +
                    getSum(resourceLarge1 + resourceLargeCenter + resourceLargeCenter)
                )}
              </span>
            </td>
          </tr>

          <tr className="tr_three">
            <td className="td_number">
              <span>5</span>
            </td>
            <td className="ch-name">
              <div className="tooltip">
                <Tooltip title="середина хребта, шлунково-кишковий тракт (печінка, підшлункова, жовчний міхур, тонкий кишечник, надниркові залози)">
                  <InfoIcon style={{ fontSize: 20, fill: '#9a9ca7' }} />
                </Tooltip>
              </div>
              <div className="info-wrapper">
                <span>Маніпура</span>
                {/*<span className="ch-info">Статус, партнерство</span>*/}
              </div>
            </td>
            <td>{getSum(resourceLargeCenter)}</td>
            <td>{getSum(resourceLargeCenter)}</td>
            <td>{getSum(getSum(resourceLargeCenter) + getSum(resourceLargeCenter))}</td>
          </tr>

          <tr className="tr_two">
            <td className="td_number">
              <span>6</span>
            </td>
            <td className="ch-name">
              <div className="tooltip">
                <Tooltip title="нирки, товстий кишечник, надниркові залози, статеві органи, поперек, сечостатева система">
                  <InfoIcon style={{ fontSize: 20, fill: '#9a9ca7' }} />
                </Tooltip>
              </div>
              <div className="info-wrapper">
                <span>Свадхістана</span>
                {/*<span className="ch-info">Радість, задоволення</span>*/}
              </div>
            </td>
            <td>
              <span>{getSum(resourceLargeCenter + resourceLarge8)}</span>
            </td>
            <td>
              <span>{getSum(resourceLargeCenter + resourceLarge5)}</span>
            </td>
            <td>
              <span>
                {getSum(
                  getSum(resourceLargeCenter + resourceLarge5) +
                    getSum(resourceLargeCenter + resourceLarge8)
                )}
              </span>
            </td>
          </tr>

          <tr className="tr_one">
            <td className="td_number">
              <span>7</span>
            </td>
            <td className="ch-name">
              <div className="tooltip">
                <Tooltip title="ноги, анус, криж">
                  <InfoIcon style={{ fontSize: 20, fill: '#9a9ca7' }} />
                </Tooltip>
              </div>
              <div className="info-wrapper">
                <span>Муладхара</span>
                {/*<span className="ch-info">Тіло, матерія</span>*/}
              </div>
            </td>
            <td>
              <span>{getSum(resourceLarge8)}</span>
            </td>
            <td>
              <span>{getSum(resourceLarge5)}</span>
            </td>
            <td>
              <span>{getSum(getSum(resourceLarge5) + getSum(resourceLarge8))}</span>
            </td>
          </tr>

          <tr className="th_footer tr_sum">
            <td className="td_number">
              <span></span>
            </td>
            <td className="ch-name">
              <div className="tooltip">
                <Tooltip title="системи: кісткова, лімфатична, зайва вага">
                  <InfoIcon style={{ fontSize: 20, fill: '#9a9ca7' }} />
                </Tooltip>
              </div>
              <div className="info-wrapper">
                <span>Загальний підсумок</span>
              </div>
            </td>
            {/*<td>*/}
            {/*  {getSum(*/}
            {/*    largeCircleValue1(mainString, userDataPersonal.birth) +*/}
            {/*      getSum(*/}
            {/*        largeCircleValue1(mainString, userDataPersonal.birth) +*/}
            {/*          largeCircleValueCenter(mainString, userDataPersonal.birth) +*/}
            {/*          largeCircleValue1(mainString, userDataPersonal.birth)*/}
            {/*      ) +*/}
            {/*      getSum(*/}
            {/*        largeCircleValue1(mainString, userDataPersonal.birth) +*/}
            {/*          largeCircleValueCenter(mainString, userDataPersonal.birth)*/}
            {/*      ) +*/}
            {/*      getSum(*/}
            {/*        largeCircleValue1(mainString, userDataPersonal.birth) +*/}
            {/*          largeCircleValueCenter(mainString, userDataPersonal.birth) +*/}
            {/*          largeCircleValueCenter(mainString, userDataPersonal.birth)*/}
            {/*      ) +*/}
            {/*      getSum(largeCircleValueCenter(mainString, userDataPersonal.birth)) +*/}
            {/*      getSum(*/}
            {/*        largeCircleValueCenter(mainString, userDataPersonal.birth) +*/}
            {/*          largeCircleValue8(mainString, userDataPersonal.birth)*/}
            {/*      ) +*/}
            {/*      getSum(largeCircleValue8(mainString, userDataPersonal.birth))*/}
            {/*  )}*/}
            {/*</td>*/}
            {/*<td>*/}
            {/*  {getSum(*/}
            {/*    largeCircleValue4(mainString, userDataPersonal.birth) +*/}
            {/*      getSum(*/}
            {/*        largeCircleValue4(mainString, userDataPersonal.birth) +*/}
            {/*          largeCircleValue4(mainString, userDataPersonal.birth) +*/}
            {/*          largeCircleValueCenter(mainString, userDataPersonal.birth)*/}
            {/*      ) +*/}
            {/*      getSum(*/}
            {/*        largeCircleValue4(mainString, userDataPersonal.birth) +*/}
            {/*          largeCircleValueCenter(mainString, userDataPersonal.birth)*/}
            {/*      ) +*/}
            {/*      getSum(*/}
            {/*        largeCircleValueCenter(mainString, userDataPersonal.birth) +*/}
            {/*          largeCircleValue4(mainString, userDataPersonal.birth) +*/}
            {/*          largeCircleValueCenter(mainString, userDataPersonal.birth)*/}
            {/*      ) +*/}
            {/*      getSum(largeCircleValueCenter(mainString, userDataPersonal.birth)) +*/}
            {/*      getSum(*/}
            {/*        largeCircleValueCenter(mainString, userDataPersonal.birth) +*/}
            {/*          largeCircleValue5(mainString, userDataPersonal.birth)*/}
            {/*      ) +*/}
            {/*      getSum(largeCircleValue5(mainString, userDataPersonal.birth))*/}
            {/*  )}*/}
            {/*</td>*/}
            <td></td>
            <td className="td_sum">
              {getSum(
                getSum(resourceLarge4 + resourceLarge1) +
                  getSum(
                    getSum(resourceLarge4 + resourceLarge4 + resourceLargeCenter) +
                      getSum(resourceLarge1 + resourceLargeCenter + resourceLarge1)
                  ) +
                  getSum(
                    getSum(resourceLarge4 + resourceLargeCenter) +
                      getSum(resourceLarge1 + resourceLargeCenter)
                  ) +
                  getSum(
                    getSum(resourceLargeCenter + resourceLarge4 + resourceLargeCenter) +
                      getSum(resourceLarge1 + resourceLargeCenter + resourceLargeCenter)
                  ) +
                  getSum(getSum(resourceLargeCenter) + getSum(resourceLargeCenter)) +
                  getSum(
                    getSum(resourceLargeCenter + resourceLarge5) +
                      getSum(resourceLargeCenter + resourceLarge8)
                  ) +
                  getSum(getSum(getSum(resourceLarge5) + getSum(resourceLarge8)))
              )}
            </td>
            <td></td>
          </tr>
        </tbody>
      </table>
    </div>
  );
};
