import React, { useEffect, useState } from 'react';
import './Purposes.scss';
import {
  getSum,
  largeCircleValue1,
  largeCircleValue2,
  largeCircleValue3,
  largeCircleValue4,
  largeCircleValue5,
  largeCircleValue6,
  largeCircleValue7,
  largeCircleValue8,
  largeCircleValueCenter,
} from '../../functions/calculator';
import { useAppSelector } from '../../hooks/redux';
import Diamond from '../../assets/dia.png';
import { calculateResourceMatrix } from '../../functions/calculateResourceMatrix';

interface IYearsTableProps {
  getEnergyValue: () => { [key: string]: number };
}

export const ResourcePurposes = ({ getEnergyValue }: IYearsTableProps) => {
  const { mainString, userDataPersonal } = useAppSelector((state) => state.storeReducer);

  const [firstCircle, setFirstCircle] = useState<string>('');
  const [secondCircle, setSecondCircle] = useState<string>('');
  const [thirdCircle, setThirdCircle] = useState<string>('');

  const resourceDate = calculateResourceMatrix(userDataPersonal.birth);
  const [dayStr, monthStr, yearStr] = resourceDate.split('.');

  const resourceLarge4 = parseInt(dayStr, 10);
  const resourceLarge1 = parseInt(monthStr, 10);
  const resourceLarge5 = parseInt(yearStr, 10);

  const resourceLarge2 = getSum(resourceLarge1 + resourceLarge4);
  const resourceLarge3 = getSum(resourceLarge1 + resourceLarge5);
  const resourceLarge8 = getSum(resourceLarge4 + resourceLarge1 + resourceLarge5);
  const resourceLarge6 = getSum(resourceLarge4 + resourceLarge8);
  const resourceLargeCenter = getSum(
    resourceLarge1 + resourceLarge4 + resourceLarge5 + resourceLarge8
  );
  const resourceLarge7 = getSum(resourceLarge5 + resourceLarge8);

  function getYearId() {
    const yearIDPlus = parseInt(userDataPersonal.yearsOld) + 40;
    if (yearIDPlus >= 80) {
      return yearIDPlus % 80;
    }
    return yearIDPlus;
  }

  useEffect(() => {
    if (document.getElementById(parseInt(userDataPersonal.yearsOld).toString())) {
      setFirstCircle(
        document.getElementById(parseInt(userDataPersonal.yearsOld).toString())!.innerHTML
      );
      console.log(getYearId());
      setSecondCircle(document.getElementById(getYearId().toString())!.innerHTML);
      setThirdCircle(
        getSum(
          parseInt(secondCircle) +
            parseInt(
              document.getElementById(parseInt(userDataPersonal.yearsOld).toString())!.innerHTML
            )
        ).toString()
      );
    } else {
      setFirstCircle('-');
      setSecondCircle('-');
      setThirdCircle('-');
    }
  }, [secondCircle]);

  return (
    <div className="purposes_container">
      {/*<h3>ПРИЗНАЧЕННЯ</h3>*/}
      <div className="purposes">
        <div className="purposes_top">
          <div className="purpose personal">
            <h3 className="purpose_h3">Призначення для себе</h3>
            {/*<p>Наше завдання, урок, який ми прийшли отримати для себе</p>*/}
            <div className="rect">
              <div className="content">
                <div className="content_row">
                  Небо:
                  <div className="circle_purpose">{getSum(resourceLarge1 + resourceLarge8)}</div>
                  <img
                    className="purposes_matrix-diamond"
                    id="diamond-1"
                    src={Diamond}
                    alt="diamond"
                  />
                  <img
                    className="purposes_matrix-diamond"
                    id="diamond-2"
                    src={Diamond}
                    alt="diamond"
                  />
                  <img
                    className="purposes_matrix-diamond"
                    id="diamond-3"
                    src={Diamond}
                    alt="diamond"
                  />
                </div>
                <div className="content_row">
                  <img
                    className="purposes_matrix-diamond"
                    id="diamond-4"
                    src={Diamond}
                    alt="diamond"
                  />
                  <img
                    className="purposes_matrix-diamond"
                    id="diamond-5"
                    src={Diamond}
                    alt="diamond"
                  />
                  <img
                    className="purposes_matrix-diamond"
                    id="diamond-6"
                    src={Diamond}
                    alt="diamond"
                  />
                  Земля:
                  <div className="circle_purpose">{getSum(resourceLarge4 + resourceLarge5)}</div>
                </div>
              </div>
              <div className="right-border">
                <span className="span left-brace-tl"></span>
                <span className="span left-brace-tr"></span>
                <br />
                <span className="span left-brace-bl"></span>
                <span className="span left-brace-br"></span>
              </div>
              <div className="circle_purpose circle_sum">
                {getSum(
                  getSum(resourceLarge1 + resourceLarge8) + getSum(resourceLarge4 + resourceLarge5)
                )}
              </div>
            </div>
          </div>
          <div className="purpose social">
            <h3 className="purpose_h3">Призначення для людей</h3>
            {/*<p>*/}
            {/*  Наша місія у цьому житті для інших, те, що ми можемо їх навчити, відкрити для них,*/}
            {/*  виконання якої несе фінансові блага від світу.*/}
            {/*</p>*/}
            <div className="rect">
              <div className="content">
                <div className="content_row word">
                  <span className="word">Ч:</span>
                  <div className="circle_purpose">{getSum(resourceLarge2 + resourceLarge7)}</div>
                </div>
                <div className="content_row word">
                  <span className="word">Ж:</span>
                  <div className="circle_purpose">{getSum(resourceLarge6 + resourceLarge3)}</div>
                </div>
              </div>
              <div className="right-border">
                <span className="span left-brace-tl"></span>
                <span className="span left-brace-tr"></span>
                <br />
                <span className="span left-brace-bl"></span>
                <span className="span left-brace-br"></span>
              </div>
              <div className="circle_purpose circle_sum">
                {getSum(
                  getSum(resourceLarge2 + resourceLarge7) + getSum(resourceLarge6 + resourceLarge3)
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
      <div className="purpose purpose_bottom">
        <div className="purpose_general">
          <h3 className="purpose_h3 purpose_h3_bot">Загальне</h3>
          {/*<p>*/}
          {/*  Те, що потрібно винести зі всього нашого життя як результат. Енергія в даній позиції*/}
          {/*  впливає абсолютно на кожну енергію, яка стоїть в нашій Матриці.*/}
          {/*</p>*/}
          <div className="">
            <div className="content circle_solo">
              <img className="purposes_matrix-diamond" id="diamond-7" src={Diamond} alt="diamond" />

              <div className="circle">
                {getSum(
                  getSum(
                    getSum(resourceLarge1 + resourceLarge8) +
                      getSum(resourceLarge4 + resourceLarge5)
                  ) +
                    getSum(
                      getSum(
                        getSum(resourceLarge2 + resourceLarge7) +
                          getSum(resourceLarge6 + resourceLarge3)
                      )
                    )
                )}
              </div>
            </div>
          </div>
        </div>
        <div className="purpose_planetary">
          <h3 className="purpose_h3 purpose_h3_bot">Планетарне</h3>
          {/*<p>Наш вклад в людство, те, як ми можемо вплинути на світ.</p>*/}
          <div className="rect">
            <div className="content circle_solo">
              <img className="purposes_matrix-diamond" id="diamond-7" src={Diamond} alt="diamond" />

              <div className="circle">
                {getSum(
                  getSum(
                    getSum(resourceLarge2 + resourceLarge7) +
                      getSum(resourceLarge6 + resourceLarge3)
                  ) +
                    getSum(
                      getSum(
                        getSum(resourceLarge1 + resourceLarge8) +
                          getSum(resourceLarge4 + resourceLarge5)
                      ) +
                        getSum(
                          getSum(
                            getSum(resourceLarge2 + resourceLarge7) +
                              getSum(resourceLarge6 + resourceLarge3)
                          )
                        )
                    )
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
      {/*<div className="own_power_code">*/}
      {/*  <h3>Ключ розширення</h3>*/}
      {/*  <div className="own_power_code-items">*/}
      {/*    <div className="own_power_code-item">*/}
      {/*      <h4 className="purpose_h4">Зона комфорту</h4>*/}
      {/*      <div className="content circle_solo">*/}
      {/*        <div className="circle">*/}
      {/*          {largeCircleValueCenter(mainString, userDataPersonal.birth)}*/}
      {/*        </div>*/}
      {/*      </div>*/}
      {/*    </div>*/}
      {/*    <div className="own_power_code-item">*/}
      {/*      <h4 className="purpose_h4">Сила Роду</h4>*/}
      {/*      <div className="content circle_solo">*/}
      {/*        <div className="circle">*/}
      {/*          {getSum(*/}
      {/*            largeCircleValue2(mainString, userDataPersonal.birth) +*/}
      {/*              largeCircleValue3(mainString, userDataPersonal.birth) +*/}
      {/*              largeCircleValue6(mainString, userDataPersonal.birth) +*/}
      {/*              largeCircleValue7(mainString, userDataPersonal.birth)*/}
      {/*          )}*/}
      {/*        </div>*/}
      {/*      </div>*/}
      {/*    </div>*/}
      {/*    <div className="own_power_code-item">*/}
      {/*      <h4 className="purpose_h4">Особистий потенціал</h4>*/}
      {/*      <div className="content circle_solo">*/}
      {/*        <div className="circle">*/}
      {/*          {getSum(*/}
      {/*            getSum(*/}
      {/*              largeCircleValue2(mainString, userDataPersonal.birth) +*/}
      {/*                largeCircleValue3(mainString, userDataPersonal.birth) +*/}
      {/*                largeCircleValue6(mainString, userDataPersonal.birth) +*/}
      {/*                largeCircleValue7(mainString, userDataPersonal.birth)*/}
      {/*            ) + largeCircleValueCenter(mainString, userDataPersonal.birth)*/}
      {/*          )}*/}
      {/*        </div>*/}
      {/*      </div>*/}
      {/*    </div>*/}
      {/*  </div>*/}
      {/*</div>*/}
      {/*<div className="map-of-year">*/}
      {/*  <h3>Карта року</h3>*/}
      {/*  <div className="map-of-year_items">*/}
      {/*    <div className="content circle_solo">*/}
      {/*      <div className="circle">{thirdCircle}</div>*/}
      {/*    </div>*/}
      {/*    <div className="content circle_solo">*/}
      {/*      <div className="circle">{secondCircle}</div>*/}
      {/*    </div>*/}
      {/*    <div className="content circle_solo">*/}
      {/*      <div className="circle">{firstCircle}</div>*/}
      {/*    </div>*/}
      {/*  </div>*/}
      {/*</div>*/}
    </div>
  );
};
