import { calculateResourceMatrix } from './calculateResourceMatrix'; // твоя основна функція
import { getSum } from './calculator'; // припустимо, це функція яка зводить число: 28 => 2+8 => 10

export interface ResourceMatrixResult {
  resourceLarge1: number;
  resourceLarge2: number;
  resourceLarge3: number;
  resourceLarge4: number;
  resourceLarge5: number;
  resourceLarge6: number;
  resourceLarge7: number;
  resourceLarge8: number;
  resourceLargeCenter: number;
}

export function calculateResourceMatrixFull(birthDate: string): ResourceMatrixResult {
  const resourceDate = calculateResourceMatrix(birthDate); // наприклад "11.03.10"
  const [dayStr, monthStr, yearStr] = resourceDate.split('.');

  const resourceLarge4 = parseInt(dayStr, 10);
  const resourceLarge1 = parseInt(monthStr, 10);
  const resourceLarge5 = parseInt(yearStr, 10);

  const resourceLarge2 = getSum(resourceLarge1 + resourceLarge4);
  const resourceLarge3 = getSum(resourceLarge1 + resourceLarge5);
  const resourceLarge8 = getSum(resourceLarge4 + resourceLarge1 + resourceLarge5);
  const resourceLarge6 = getSum(resourceLarge4 + resourceLarge8);
  const resourceLargeCenter = getSum(
    resourceLarge1 + resourceLarge4 + resourceLarge5 + resourceLarge8
  );
  const resourceLarge7 = getSum(resourceLarge5 + resourceLarge8);

  return {
    resourceLarge1,
    resourceLarge2,
    resourceLarge3,
    resourceLarge4,
    resourceLarge5,
    resourceLarge6,
    resourceLarge7,
    resourceLarge8,
    resourceLargeCenter,
  };
}
