// Функція для зведення числа до значення < 22
function reduceToUnder22(num: number): number {
  while (num >= 22) {
    num = num
      .toString()
      .split('')
      .reduce((sum: number, digit: string) => sum + parseInt(digit, 10), 0);
  }
  return num;
}

// Основна функція
export function calculateResourceMatrix(dateStr: string): string {
  const parts: string[] = dateStr.split('.');

  if (parts.length !== 3) {
    throw new Error('Неправильний формат дати. Використовуй формат: дд.мм.рррр');
  }

  const [dayStr, monthStr, yearStr] = parts;

  const day: number = parseInt(dayStr, 10);
  const month: number = parseInt(monthStr, 10);
  const yearDigits: number[] = yearStr.split('').map((char: string): number => parseInt(char, 10));

  const yearSum: number = yearDigits.reduce((sum: number, digit: number) => sum + digit, 0);
  const reducedYear: number = reduceToUnder22(yearSum);

  const dayPlus22: number = reduceToUnder22(day + 22);
  const monthPlus22: number = reduceToUnder22(month + 22);
  const yearPlus22: number = reduceToUnder22(reducedYear + 22);

  const format = (num: number): string => (num < 10 ? `0${num}` : `${num}`);

  return `${format(dayPlus22)}.${format(monthPlus22)}.${format(yearPlus22)}`;
}
